mapper.sql:
WHERE n.delete_yn = 'N'

  AND n.recipient_user_id = #{search.recipientUserId}


  AND n.notification_type = #{search.notificationType}


  AND n.read_yn = #{search.readYn}


  AND n.title LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:
SELECT 


ORDER BY n.created_at DESC
 LIMIT #{search.pageSize} OFFSET #{search.offset}

mapper.update:
UPDATE tb_notification
   SET delete_yn  = 'Y',
       updated_at = NOW()
 WHERE notification_id   = #{notificationId}
   AND recipient_user_id = #{recipientUserId}
   AND delete_yn         = 'N'

mapper.delete:
DELETE FROM tb_notification
 WHERE delete_yn  = 'Y'
   AND updated_at < #{cutoff}

DELETE FROM tb_notification
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_notification
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
